    @css_provider = Gtk::CssProvider.new
    css_data = <<-CSS
      .combatical-window {
        background-color: #{s[:bg]};
        color: #{s[:fg]};
      }
      .combatical-section-header {
        background-color: #{s[:bg3]};
        color: #{s[:fg]};
        padding: 5px 10px;
        font-weight: bold;
        border-radius: 3px;
      }
      .combatical-box-frame {
        border: 1px solid #{s[:border]};
        border-radius: 3px;
      }
      .combatical-drop-indicator {
        border-bottom: 2px solid #4488FF;
      }
      .combatical-pool-frame {
        border: 2px solid transparent;
      }
      .combatical-pool-hover {
        border-color: #44BB44;
      }
      .combatical-box-scroll {
        background-color: #{s[:box_bg] || 'black'};
      }
      .combatical-box-scroll viewport {
        background-color: #{s[:box_bg] || 'black'};
      }
      .combatical-box-scroll viewport box {
        background-color: #{s[:box_bg] || 'black'};
      }
      .combatical-box-scroll viewport grid {
        background-color: #{s[:box_bg] || 'black'};
      }
      .combatical-box-scroll viewport eventbox {
        background-color: #{s[:box_bg] || 'black'};
      }
      .combatical-box-scroll viewport eventbox box {
        background-color: #{s[:box_bg] || 'black'};
      }
      .combatical-box-scroll viewport flowbox {
        background-color: #{s[:box_bg] || 'black'};
      }
      .combatical-box-scroll viewport flowbox flowboxchild {
        background-color: #{s[:box_bg] || 'black'};
        padding: 0;
      }
      .combatical-box-scroll viewport flowbox flowboxchild eventbox {
        background-color: #{s[:box_bg] || 'black'};
      }
      .combatical-target-bg {
        background-color: #{s[:box_bg] || 'black'};
      }
      .combatical-box-bg {
        background-color: #{s[:box_bg] || 'black'};
      }
      .combatical-ability-row {
        background-color: #{s[:box_bg] || 'black'};
      }
      .combatical-ability-label-shadow {
        text-shadow: 0px 0px 2px rgba(0,0,0,0.9);
      }
      .combatical-box-scroll scrollbar,
      .combatical-box-scroll scrollbar contents,
      .combatical-box-scroll scrollbar trough,
      .combatical-box-scroll scrollbar button,
      .combatical-box-scroll scrollbar button image {
        background-color: #{s[:box_bg] || 'black'};
        border: none;
        outline: none;
        box-shadow: none;
        min-width: 0;
        min-height: 0;
      }
      .combatical-box-scroll scrollbar slider {
        background-color: #{s[:border] || '#383838'};
        border: none;
        outline: none;
        box-shadow: none;
        border-radius: 4px;
        min-width: 6px;
        min-height: 6px;
      }
      .combatical-box-scroll junction {
        background-color: #{s[:box_bg] || 'black'};
        border: none;
      }
      .combatical-lock-flash {
        border: 3px solid #FF2222;
        margin: -3px;
        background-color: rgba(255, 0, 0, 0.25);
        border-radius: 4px;
      }
    CSS

    @css_provider.load(data: css_data)

    Gtk::StyleContext.add_provider_for_screen(
      Gdk::Screen.default,
      @css_provider,
      Gtk::StyleProvider::PRIORITY_APPLICATION
    )

